{
    ra_mode_t prev_mode;
    int rejected = 0;
    adcs_quat_t qc, qt, qe, qc_conj;
    adcs_vec3_t e, w;
    double angle, rate_mag;
    adcs_vec3_t I_new;
    double kp_eff, kd_eff, ki_eff;
    adcs_actuator_limit_t lim;
    adcs_vec3_t tau_unlim, tau_lim;
    unint32 sat_mask = 0;
    int i;

    /* --- config validation (every cycle) --- */
    if ((ra_config.fine_enter_rad < 0.0) ||
        (ra_config.fine_enter_rad >= ra_config.fine_exit_rad) ||
        (ra_config.fine_exit_rad > ADCS_PI) ||
        (ra_config.hold_enter_rad < 0.0) ||
        (ra_config.hold_enter_rad >= ra_config.hold_exit_rad) ||
        (ra_config.hold_exit_rad > ra_config.fine_enter_rad) ||
        (ra_config.rate_enter_rad_s <= ra_config.hold_rate_exit_rad_s) ||
        (ra_config.hold_rate_exit_rad_s <= ra_config.hold_rate_rad_s) ||
        (ra_config.hold_rate_rad_s < 0.0) ||
        (ra_config.rate_enter_rad_s >= ra_config.rate_exit_rad_s) ||
        (!isfinite(ra_config.dt_s)) || (ra_config.dt_s <= 0.0) ||
        (!isfinite(ra_config.integral_limit_rad_s)) ||
        (ra_config.integral_limit_rad_s <= 0.0) ||
        (!isfinite(ra_config.torque_limit_nm)) ||
        (ra_config.torque_limit_nm <= 0.0) ||
        (!isfinite(ra_config.kp)) || (ra_config.kp < 0.0) ||
        (!isfinite(ra_config.kd)) || (ra_config.kd < 0.0) ||
        (!isfinite(ra_config.ki)) || (ra_config.ki < 0.0) ||
        (ra_config.rate_samples < 1U) || (ra_config.rate_samples > 20U) ||
        (ra_config.fine_samples < 1U) || (ra_config.fine_samples > 20U) ||
        (ra_config.hold_samples < 1U) || (ra_config.hold_samples > 20U) ||
        (ra_config.max_bad_samples < 1U) || (ra_config.max_bad_samples > 20U))
        rejected = 1;

    if (!rejected) {
        if (((ra_input.enable != 0) && (ra_input.enable != 1)) ||
            ((ra_input.valid != 0) && (ra_input.valid != 1)))
            rejected = 1;
    }

    if (!rejected && (ra_input.enable == 0)) {
        ra_state.mode = RA_OFF;
        ra_state.transition_samples = 0U;
        ra_state.bad_samples = 0U;
        ra_state.integral_error_rad_s = (adcs_vec3_t){0, 0, 0};
        ra_output.mode = RA_OFF;
        ra_output.error_angle_rad = 0.0;
        ra_output.rate_magnitude_rad_s = 0.0;
        ra_output.torque_nm = (adcs_vec3_t){0, 0, 0};
        ra_output.bad_samples = 0U;
        ra_output.saturation_mask = 0U;
        return;
    }

    if (!rejected && (ra_input.valid == 0))
        rejected = 1;
    if (!rejected && ((ra_input.current_q_bi == NULL) ||
                      (ra_input.target_q_bi == NULL) ||
                      (ra_input.body_rate_rad_s == NULL)))
        rejected = 1;
    if (!rejected && !adcs_is_finite_vec3(ra_input.body_rate_rad_s))
        rejected = 1;
    if (!rejected) {
        if (adcs_quat_normalize(ra_input.current_q_bi, &qc) != ADCS_OK)
            rejected = 1;
        else if (adcs_quat_normalize(ra_input.target_q_bi, &qt) != ADCS_OK)
            rejected = 1;
    }

    if (rejected) {
        ra_state.transition_samples = 0U;
        ra_state.integral_error_rad_s = (adcs_vec3_t){0, 0, 0};
        ra_state.bad_samples += 1U;
        if (ra_state.bad_samples >= ra_config.max_bad_samples)
            ra_state.mode = RA_FAULT;
        ra_output.mode = ra_state.mode;
        ra_output.error_angle_rad = 0.0;
        ra_output.rate_magnitude_rad_s = 0.0;
        ra_output.torque_nm = (adcs_vec3_t){0, 0, 0};
        ra_output.bad_samples = ra_state.bad_samples;
        ra_output.saturation_mask = 0U;
        return;
    }

    /* --- attitude error --- */
    qc_conj = adcs_quat_conjugate(&qc);
    qe = adcs_quat_multiply(&qt, &qc_conj);
    if (qe.w < 0.0) {
        qe.w = -qe.w;
        qe.x = -qe.x;
        qe.y = -qe.y;
        qe.z = -qe.z;
    }
    {
        double qv_norm = sqrt(qe.x * qe.x + qe.y * qe.y + qe.z * qe.z);
        if (qv_norm < ADCS_EPS_NORM) {
            angle = 0.0;
            e = (adcs_vec3_t){0, 0, 0};
        } else {
            double hangle = atan2(qv_norm, qe.w);
            double s;
            angle = 2.0 * hangle;
            if (angle > ADCS_PI)
                angle = ADCS_PI;
            s = hangle / qv_norm;
            e = (adcs_vec3_t){s * qe.x, s * qe.y, s * qe.z};
        }
    }
    w = *(ra_input.body_rate_rad_s);
    rate_mag = adcs_vec3_norm(&w);

    /* --- OFF: choose RATE_DAMP or COARSE --- */
    if (ra_state.mode == RA_OFF) {
        ra_state.transition_samples = 0U;
        if (rate_mag > ra_config.rate_enter_rad_s)
            ra_state.mode = RA_RATE_DAMP;
        else
            ra_state.mode = RA_COARSE;
        /* continue through control law below */
    }

    /* --- transition logic --- */
    if (ra_state.mode == RA_RATE_DAMP) {
        if (rate_mag >= ra_config.rate_exit_rad_s) {
            ra_state.transition_samples = 0U;
        } else if (rate_mag <= ra_config.rate_enter_rad_s) {
            ra_state.transition_samples += 1U;
            if (ra_state.transition_samples >= ra_config.rate_samples) {
                ra_state.mode = RA_COARSE;
                ra_state.transition_samples = 0U;
            }
        } else {
            ra_state.transition_samples = 0U;
        }
    } else if (ra_state.mode == RA_COARSE) {
        if ((angle <= ra_config.fine_enter_rad) &&
            (rate_mag <= ra_config.rate_enter_rad_s)) {
            ra_state.transition_samples += 1U;
            if (ra_state.transition_samples >= ra_config.fine_samples) {
                ra_state.mode = RA_FINE;
                ra_state.transition_samples = 0U;
            }
        } else {
            ra_state.transition_samples = 0U;
        }
    } else if (ra_state.mode == RA_FINE) {
        if ((angle >= ra_config.fine_exit_rad) ||
            (rate_mag >= ra_config.rate_exit_rad_s)) {
            ra_state.mode = RA_COARSE;
            ra_state.integral_error_rad_s = (adcs_vec3_t){0, 0, 0};
            ra_state.transition_samples = 0U;
        } else if ((angle <= ra_config.hold_enter_rad) &&
                   (rate_mag <= ra_config.hold_rate_rad_s)) {
            ra_state.transition_samples += 1U;
            if (ra_state.transition_samples >= ra_config.hold_samples) {
                ra_state.mode = RA_HOLD;
                ra_state.transition_samples = 0U;
            }
        } else {
            ra_state.transition_samples = 0U;
        }
    } else if (ra_state.mode == RA_HOLD) {
        if ((angle >= ra_config.hold_exit_rad) ||
            (rate_mag >= ra_config.hold_rate_exit_rad_s)) {
            ra_state.mode = RA_FINE;
            ra_state.transition_samples = 0U;
        }
    }
    /* RA_FAULT remains latched */

    /* --- control law using mode reached this cycle --- */
    if (ra_state.mode == RA_RATE_DAMP) {
        kp_eff = 0.0;
        kd_eff = ra_config.kd;
        ki_eff = 0.0;
    } else if (ra_state.mode == RA_COARSE) {
        kp_eff = ra_config.kp;
        kd_eff = ra_config.kd;
        ki_eff = 0.0;
    } else {
        kp_eff = ra_config.kp;
        kd_eff = ra_config.kd;
        ki_eff = ra_config.ki;
    }

    I_new = ra_state.integral_error_rad_s;
    if ((ra_state.mode == RA_FINE) || (ra_state.mode == RA_HOLD)) {
        double prop_x = ra_state.integral_error_rad_s.x + e.x * ra_config.dt_s;
        double prop_y = ra_state.integral_error_rad_s.y + e.y * ra_config.dt_s;
        double prop_z = ra_state.integral_error_rad_s.z + e.z * ra_config.dt_s;
        I_new.x = ADCS_CLAMP(prop_x, -ra_config.integral_limit_rad_s,
                             ra_config.integral_limit_rad_s);
        I_new.y = ADCS_CLAMP(prop_y, -ra_config.integral_limit_rad_s,
                             ra_config.integral_limit_rad_s);
        I_new.z = ADCS_CLAMP(prop_z, -ra_config.integral_limit_rad_s,
                             ra_config.integral_limit_rad_s);
    }

    tau_unlim.x = -kp_eff * e.x - kd_eff * w.x - ki_eff * I_new.x;
    tau_unlim.y = -kp_eff * e.y - kd_eff * w.y - ki_eff * I_new.y;
    tau_unlim.z = -kp_eff * e.z - kd_eff * w.z - ki_eff * I_new.z;

    lim.min_value = -ra_config.torque_limit_nm;
    lim.max_value = ra_config.torque_limit_nm;
    lim.max_slew_per_s = 0.0;

    {
        double uvals[3];
        double tvals[3];
        uvals[0] = tau_unlim.x;
        uvals[1] = tau_unlim.y;
        uvals[2] = tau_unlim.z;
        for (i = 0; i < 3; i++) {
            (void)adcs_limit_scalar(uvals[i], &lim, &tvals[i]);
            if (tvals[i] != uvals[i])
                sat_mask |= (unint32)(1U << i);
        }
        tau_lim = (adcs_vec3_t){tvals[0], tvals[1], tvals[2]};

        if (ki_eff != 0.0) {
            for (i = 0; i < 3; i++) {
                double Iold_i, Inew_i, dI, tlim_i, tau_re, tau_chk;
                if (tvals[i] == uvals[i])
                    continue;
                Iold_i = (i == 0) ? ra_state.integral_error_rad_s.x :
                         (i == 1) ? ra_state.integral_error_rad_s.y :
                                    ra_state.integral_error_rad_s.z;
                Inew_i = (i == 0) ? I_new.x : (i == 1) ? I_new.y : I_new.z;
                tlim_i = tvals[i];
                dI = ki_eff * (Inew_i - Iold_i);
                if (((tlim_i > 0.0) && (dI < 0.0)) ||
                    ((tlim_i < 0.0) && (dI > 0.0))) {
                    double e_i = (i == 0) ? e.x : (i == 1) ? e.y : e.z;
                    double w_i = (i == 0) ? w.x : (i == 1) ? w.y : w.z;
                    if (i == 0) I_new.x = Iold_i;
                    if (i == 1) I_new.y = Iold_i;
                    if (i == 2) I_new.z = Iold_i;
                    tau_re = -kp_eff * e_i - kd_eff * w_i - ki_eff * Iold_i;
                    (void)adcs_limit_scalar(tau_re, &lim, &tau_chk);
                    if (i == 0) tau_lim.x = tau_chk;
                    if (i == 1) tau_lim.y = tau_chk;
                    if (i == 2) tau_lim.z = tau_chk;
                }
            }
        }
    }

    ra_state.integral_error_rad_s = I_new;
    ra_state.bad_samples = 0U;

    ra_output.mode = ra_state.mode;
    ra_output.error_angle_rad = angle;
    ra_output.rate_magnitude_rad_s = rate_mag;
    ra_output.torque_nm = tau_lim;
    ra_output.bad_samples = 0U;
    ra_output.saturation_mask = sat_mask;
    return;
}

